import{_ as t,c as i,a0 as e,o as s}from"./chunks/framework.BN8gA4Um.js";const g=JSON.parse('{"title":"What is LangChain?","description":"","frontmatter":{"title":"What is LangChain?"},"headers":[],"relativePath":"langchain/what-is-langchain.md","filePath":"langchain/what-is-langchain.md"}'),n={name:"langchain/what-is-langchain.md"};function h(l,a,r,o,d,p){return s(),i("div",null,[...a[0]||(a[0]=[e(`<h1 id="what-is-langchain" tabindex="-1">What is LangChain? <a class="header-anchor" href="#what-is-langchain" aria-label="Permalink to &quot;What is LangChain?&quot;">​</a></h1><p>LangChain is an <strong>orchestration framework</strong> — it doesn&#39;t replace the LLM, it sits on top of it and manages everything around the model call: prompts, context, tools, memory, and output handling.</p><h2 id="the-core-idea-everything-is-a-runnable" tabindex="-1">The Core Idea: Everything Is a Runnable <a class="header-anchor" href="#the-core-idea-everything-is-a-runnable" aria-label="Permalink to &quot;The Core Idea: Everything Is a Runnable&quot;">​</a></h2><p>Modern LangChain (post-LCEL) is built around one interface: <code>Runnable</code>. A prompt is a Runnable. A chat model is a Runnable. An output parser is a Runnable. Even a retriever is a Runnable.</p><p>Because everything shares the same interface, they can all be:</p><ul><li><strong>Piped together</strong> with <code>|</code></li><li><strong>Run in parallel</strong> with <code>RunnableParallel</code></li><li><strong>Streamed</strong> token-by-token with <code>.stream()</code></li><li><strong>Batched</strong> with <code>.batch()</code></li><li><strong>Run async</strong> with <code>.ainvoke()</code></li></ul><p>This is the single biggest design decision in LangChain — once you understand <code>Runnable</code>, the rest of the framework is just &quot;which building blocks implement it.&quot;</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># All of these are Runnables, and can be composed the same way</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">prompt.invoke(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">model.invoke(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">retriever.invoke(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">chain.invoke(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># a chain is just Runnables piped together</span></span></code></pre></div><h2 id="langchain-s-package-ecosystem" tabindex="-1">LangChain&#39;s Package Ecosystem <a class="header-anchor" href="#langchain-s-package-ecosystem" aria-label="Permalink to &quot;LangChain&#39;s Package Ecosystem&quot;">​</a></h2><p>LangChain isn&#39;t one package — it&#39;s split up so you only install what you need:</p><table tabindex="0"><thead><tr><th>Package</th><th>What it contains</th></tr></thead><tbody><tr><td><code>langchain-core</code></td><td>Base abstractions: <code>Runnable</code>, prompts, messages, output parsers</td></tr><tr><td><code>langchain-community</code></td><td>Third-party integrations (vector stores, document loaders, tools)</td></tr><tr><td><code>langchain-openai</code>, <code>langchain-anthropic</code>, etc.</td><td>Provider-specific model integrations</td></tr><tr><td><code>langchain</code></td><td>Higher-level chains, agents, and retrieval logic built on core</td></tr><tr><td><code>langgraph</code></td><td>A separate, more powerful library for building stateful agent workflows (covered in its own section)</td></tr><tr><td><code>langsmith</code></td><td>Observability/tracing — not required, but useful for debugging chains</td></tr></tbody></table><h2 id="why-provider-agnostic-matters" tabindex="-1">Why &quot;Provider-Agnostic&quot; Matters <a class="header-anchor" href="#why-provider-agnostic-matters" aria-label="Permalink to &quot;Why &quot;Provider-Agnostic&quot; Matters&quot;">​</a></h2><p>Because chat models implement the same <code>Runnable</code> interface regardless of provider, switching from OpenAI to Anthropic is often just changing one line:</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Before</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> langchain_openai </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ChatOpenAI</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">model </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ChatOpenAI(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">model</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;gpt-4o&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># After</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> langchain_anthropic </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ChatAnthropic</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">model </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ChatAnthropic(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">model</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;claude-sonnet-4-6&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>Everything downstream — prompts, parsers, chains — stays the same.</p><h2 id="langchain-vs-calling-the-api-directly" tabindex="-1">LangChain vs. Calling the API Directly <a class="header-anchor" href="#langchain-vs-calling-the-api-directly" aria-label="Permalink to &quot;LangChain vs. Calling the API Directly&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Direct API call</th><th>LangChain</th></tr></thead><tbody><tr><td>Single prompt, single response</td><td>✅ Simpler</td><td>Unnecessary overhead</td></tr><tr><td>Swapping providers</td><td>Rewrite integration code</td><td>Change one line</td></tr><tr><td>RAG pipeline</td><td>Build retrieval logic yourself</td><td>Pre-built retriever interfaces</td></tr><tr><td>Agents with tools</td><td>Build the tool-calling loop yourself</td><td><code>AgentExecutor</code> handles it</td></tr><tr><td>Debugging multi-step chains</td><td>Manual print statements</td><td>LangSmith tracing</td></tr></tbody></table><h2 id="langchain-vs-langgraph" tabindex="-1">LangChain vs. LangGraph <a class="header-anchor" href="#langchain-vs-langgraph" aria-label="Permalink to &quot;LangChain vs. LangGraph&quot;">​</a></h2><p>A common point of confusion: <strong>LangChain</strong> is best for linear or lightly-branching pipelines (RAG, simple agents). <strong>LangGraph</strong> (built by the same team) is for workflows that need cycles, complex state, or human-in-the-loop control — like a multi-agent system where agents call each other repeatedly. You&#39;ll see this distinction again in the <a href="/NextGen-AI/orchestration/">Orchestration Frameworks</a> section.</p><h2 id="what-s-next" tabindex="-1">What&#39;s Next <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s Next&quot;">​</a></h2><p>Next: <a href="/NextGen-AI/langchain/installation.html">Installation</a> to get your environment set up, followed by <a href="/NextGen-AI/langchain/langchain-expression-language.html">LCEL</a> where you&#39;ll build your first real chain.</p>`,21)])])}const k=t(n,[["render",h]]);export{g as __pageData,k as default};
